"""Report measured residuals, rejected numerical candidates and uncertainty."""
import html,shutil,sys
from pathlib import Path
import numpy as np
from investigate_dielectric3d_polarization import read
from analyze_dielectric3d import z
from build_dielectric3d_polarization_report import table,pc

def main(root):
    w=root/'work/d3res';out=root/'outputs/differt-bridge/examples/dielectric3d_residual';out.mkdir(parents=True,exist_ok=True)
    a=read(w/'analysis.json');assert a['status']=='passed';t=a['target'];last=t['series'][-1];old=next(v for v in t['series'] if v['resolution']==96)
    analytic=read(w/'sampling_validation.json');assess=read(w/'sampling_assessment.json');resource=read(w/'resource_selection.json');offgrid=read(w/'offgrid_validation.json')
    conv=table(['Independent reference','Production 16/32 RMS','Research 32/64 RMS','BIE64 RMS','Previous mesh → this mesh','Production median / p95 phase'],[(v['label'],pc(v['companion']['complex_rms']),pc(v['candidate']['complex_rms']),pc(v['bie64']['complex_rms']),pc(v['mesh_change']['complex_rms']) if v['mesh_change'] else '—',f'{v["companion"]["phase_median_abs_deg"]:.3f}° / {v["companion"]["phase_p95_abs_deg"]:.3f}°') for v in t['series']])
    extrap=table(['FEM-only order-2 estimate','Production discrepancy','Research candidate discrepancy','Estimate vs fine mesh'],[(f'{v["coarse"]}/{v["fine"]}',pc(v['companion']['complex_rms']),pc(v['candidate']['complex_rms']),pc(v['distance_from_fine'])) for v in t['extrapolation_diagnostics']])
    planes=table(['q','Mesh','Original vector / z→x error','Cubic vector / z→x error'],[(str(row['q']),v['resolution'],f'{pc(v["original_error"])} / {pc(v["original_zx_error"])}',f'{pc(v["cubic_error"])} / {pc(v["cubic_zx_error"])}') for row in analytic['planes'] for v in row['levels']])
    offplanes=table(['Off-grid q','Mesh','Original vector / z→x error','Cubic vector / z→x error'],[(str(row['q']),v['resolution'],f'{pc(v["original_error"])} / {pc(v["original_zx_error"])}',f'{pc(v["cubic_error"])} / {pc(v["cubic_zx_error"])}') for row in offgrid['planes'] for v in row['levels']])
    recover=table(['Wedge mesh','Sampling-only field change','Production vs cubic diagnostic','Candidate vs cubic diagnostic'],[(v['resolution'],pc(v['sampling_change']['complex_rms']),pc(v['companion']['complex_rms']),pc(v['candidate']['complex_rms'])) for v in t['sampling_diagnostics']])
    groups=[v for v in a['comparisons'] if v['engine']=='sionna' and v['shadow_refined'] and v['shadow_refined']['complex_rms'] is not None]
    complete=table(['Group','Reference','Production shadow RMS','Research candidate RMS','Latest reference increment'],[(v['name'],v['reference_label'],pc(v['shadow_refined']['complex_rms']),pc(v['candidate_shadow']['complex_rms']) if v['candidate_shadow'] else 'not computed',pc(v['reference_shadow_change']['complex_rms'])) for v in sorted(groups,key=lambda v:v['shadow_refined']['complex_rms'],reverse=True)])
    target=next(r for r in a['comparisons'] if r['engine']=='sionna' and r['name']==t['name']);ref=z(target['reference']);current=z(target['field']);candidate=z(target['candidate'])
    ports=table(['Wedge angle φ','Strict shadow','Production complex error','Candidate complex error','Production phase','Candidate phase'],[(f'{angle:g}°','yes' if target['shadow_mask'][i] else 'no',pc(abs(current[i]-ref[i])/abs(ref[i])),pc(abs(candidate[i]-ref[i])/abs(ref[i])),f'{np.angle(current[i]*ref[i].conjugate(),deg=True):+.4f}°',f'{np.angle(candidate[i]*ref[i].conjugate(),deg=True):+.4f}°') for i,angle in enumerate(target['study']['angles'])])
    modal=table(['Real q interval','Production residual norm','Candidate residual norm','Last reference-change norm'],[(str(v['q_range']),*[f'{v["norms"][k]:.6g}' for k in ('current','candidate','reference')]) for v in a['modal_diagnosis']['intervals']])
    tail=table(['Tail q','FEM64→128 relative mode change','Weighted change / target norm'],[(str(v['q']),pc(v['relative_modal_change']),pc(v['weighted_change_relative_to_target'])) for v in a['tail_controls']])
    style=(root/'outputs/differt-bridge/examples/dielectric3d_polarization/index.html').read_text(encoding='utf-8').split('<style>',1)[1].split('</style>',1)[0]
    page=f'''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Remaining polarization residual: independent refinement</title><style>{style}</style><body>
<p><a href="../../../../index.html">All project results</a> · <a href="../dielectric3d_polarization/index.html">Previous 1.56% study</a></p>
<h1>Remaining polarization residual: independent refinement</h1>
<div class="box"><p><strong>The unchanged production companion measures {pc(last['companion']['complex_rms'])} against the further refined reference, compared with {pc(old['companion']['complex_rms'])} in the preceding study.</strong> Its median absolute phase residual is {last['companion']['phase_median_abs_deg']:.4f}°. The last reference increment is {pc(last['mesh_change']['complex_rms'])}; it is a sensitivity measurement, not a certified error bound.</p>
<p>A separate, unfitted <strong>research BIE32/64 candidate</strong> measures {pc(last['candidate']['complex_rms'])} against the same reference. Both native ray tracers and the default BIE16/32 companion remain unchanged.</p></div>
<h2>Regenerated comparison animation</h2><video controls preload="metadata" poster="previews/frame_0361.png" src="Sionna_vs_DiffeRT_Residual.mp4"></video>
<p>60 seconds · 1600×900 · 24 fps · <a href="Sionna_vs_DiffeRT_Residual.mp4">Video</a> · <a href="Dielectric3D_Residual_Comparison.blend">Blender timeline</a>. The two workflows share the labelled full-wave companion. Native paths provide geometry context. The research candidate has its own chapter; it is not silently substituted into production.</p>
<h2>Fixed physical problem and independent calculations</h2>
<p>The target remains <code>{t['name']}</code>: z-oriented electric point transmitter and x-oriented receiver, εr≈7.1−1.1i, source radius 1.25 λ, φ=43.5°, z=−0.2 λ, receiver radius 2.3 λ and z=0.7 λ. Angles φ are counterclockwise from +y; Cartesian azimuth from +x is 90°+φ. All 14 ports remain, including eight strict-shadow samples. No port removal, gain fitting, phase fitting, material change or geometry change is used.</p>
<p>The volume FEM and boundary-integral operators are independently implemented project codes. They share the declared Fourier convention and analytically normalized free-space term. Earlier normalization, spectral, domain and PML controls remain linked in the previous study; fresh plane-interface and tail controls are included here. These are canonical single-frequency infinite-wedge calculations, not third-party certification of arbitrary finite 3D Blender geometry.</p>
<h2>Further spatial reference convergence</h2>{conv}
<p>Only real(q)&lt;7 receives the finer spatial meshes; the explicitly audited FEM64 tail is retained at the other 32 quadrature nodes. Spectral order is 8, contour height 0.5, qmax=24, physical inner domain 2.5 λ, PML thickness 1.5 λ and strength 4 throughout. The original bilinear/central-gradient recovery remains the selected reference. Labels identify mixed resolution rather than implying uniform FEM128.</p>
<p>The final reference increment shifts median absolute phase by {last['mesh_change']['phase_median_abs_deg']:.4f}° and p95 by {last['mesh_change']['phase_p95_abs_deg']:.4f}°. Full target-source vector fields are retained; all covered receiver polarizations receive the finer reference in the population table.</p>
<p>The same source-z modes also cover the existing receiver heights 0.7 λ and 2.2 λ by exact Fourier-z reweighting. All 64 old modal selections match exactly, and reconstructing the earlier complete FEM64 field differs by {a['height_reconstruction']['synthesis_relative_error']:.3g} relative. This supplies six refined source/receiver-polarization groups without additional volume solves. Fresh tail-probe sensitivity is checked at both heights and every receive polarization; the largest weighted probe change is {pc(max(v['weighted_change_relative_to_target'] for v in a['extended_tail_controls']))}. <a href="height_synthesis_validation.json">Reconstruction evidence</a>.</p>
<h2>Reference-only limiting estimates</h2>{extrap}
<p>The assumed second-order estimates use FEM fields alone: (r²Ffine−Fcoarse)/(r²−1). They use no BIE values to choose weights. Corner singularities, interpolation and unequal grid intervals can affect convergence. These diagnostics are not selected references or certified continuum bounds, and they retain the common FEM64 tail bias.</p>
<h2>Investigating the residual contributions</h2>{modal}
<p>These are norms of coherently summed, weighted Fourier contributions to the target shadow residual. The interval norms do not add because the fields interfere. Summing the complex contributions is checked against the complete reported field residual. This distinguishes changes in the reference from the separate BIE resolution change.</p>
<h2>Field-recovery candidate: rejected for general use</h2>
<p>A tensor cubic stencil was tested on the same FEM nodal solutions, restricted to homogeneous vacuum away from the material interface and PML. Polynomial values and derivatives through cubic degree were checked exactly. Analytic planar-interface Fresnel integrals then tested all nine dyadic components at two receiver locations:</p>{planes}
<p>The z→x component improves in these controls, while the full-vector error worsens. Therefore the cubic method is not adopted as a general correction. The existing reference passes the stricter independent vector and z→x checks on refinement, and the vacuum scattered field remains {analytic['vacuum_maximum']:.3g}. The cubic wedge fields remain visible as diagnostics, including any apparent improvement:</p>{recover}
<p><a href="sampling_validation.json">Raw sampling experiment, including failed candidate status</a> · <a href="sampling_assessment.json">Separate validation of the retained reference method</a>.</p>
<h3>Additional receivers between grid nodes</h3><p>The preceding planar receivers align with every mesh. A separate control uses receivers (−0.87,−1.13,0.7) λ and (−0.47,1.37,0.7) λ, which lie between nodes at all three resolutions. It tests both field interpolation and gradient recovery against the analytic Fresnel integral, for all nine dyadic components.</p>{offplanes}<p>The cubic vector errors are slightly smaller in these off-grid controls. Its mixed performance across aligned and off-grid tests does not support a general replacement. <a href="offgrid_validation.json">Off-grid control receipt and complete fields</a>. These planar checks validate recovery away from the material interface; they do not bound a corner singularity.</p>
<h2>Finer boundary-integral candidate</h2>
<p>The existing product uses 2 BIE32−BIE16. The research candidate uses the same equations and fixed first-order extrapolation 2 BIE64−BIE32, with all 64 spectral nodes recomputed at BIE64. It uses no Maxwell field to choose coefficients. The full old holdout-b material sweep covers both sources, both heights and all nine polarizations; whole-batch scene validation runs before solving.</p>
<p>Among {a['candidate_summary']['groups']} non-null shadow groups, {a['candidate_summary']['improved']} improve against their declared selected references. The complete table below includes worsening groups. Most groups retain FEM64 references, so apparent regressions can include reference discretization error. The candidate remains a research result for this material; broad production validation is not inferred from a single-material sweep.</p>
<h2>Every target angle</h2>{ports}
<p>Differences are candidate/production minus reference, with phase wrapped to ±180°. All target ports are non-null. Strict-shadow aggregation excludes ±0.02° around the shadow transition.</p>
<h2>Tail, boundary and reciprocity checks</h2>{tail}
<p>The fresh FEM128 tail probes test the spatial sensitivity of two retained FEM64 tail nodes. They do not certify every tail node or bound the unknown continuum tail. Across {a['boundaries']['stencils']} retained shadow-boundary stencils, fields are finite, maximum normalized span discrepancy is {pc(a['boundaries']['maximum_span_error'])}, and maximum complex-field discrepancy is {pc(a['boundaries']['maximum_field_rms'])}, excluding reference RMS ≤10⁻⁹. The unchanged production reciprocity discrepancy remains {pc(a['reciprocity']['relative_error'])}; continuity and reciprocity are not absolute-accuracy guarantees.</p>
<p>The research candidate also retains all {a['boundaries']['candidate_stencils']} holdout-b boundary stencils. Its maximum normalized span discrepancy is {pc(a['boundaries']['candidate_maximum_span_error'])}, and maximum complex-field discrepancy there is {pc(a['boundaries']['candidate_maximum_field_rms'])}, using each declared reference. These are numerical continuity diagnostics; the candidate has not received a new full reciprocity campaign or cross-material production qualification.</p>
<h2>All retained groups and remaining limitations</h2><p>The largest production group is <code>{a['worst_group']['name']}</code>, {pc(a['worst_group']['metrics']['complex_rms'])}, using {html.escape(a['worst_group']['reference_label'])}. Reference accuracy varies across the benchmark. Groups outside the newly refined ports retain their previous measured reference increments; they are not assigned zero uncertainty.</p><details><summary>Complete non-null group table</summary>{complete}</details>
<p>The native UTD coefficients, external runtime installations, Blender extensions, ordinary scene workflow and obstacle guards are preserved. Extra obstacles and unsupported domains continue to fail closed in the shared companion. This report does not supply a general finite-object diffraction correction, broadband CIR or differentiable replacement for either engine.</p>
<h2>Resource investigation</h2><p>{html.escape(resource['decision'])}</p><p>Every accepted solve must pass the residual gate in the original Maxwell matrix. Same-equation comparisons, allocation failures, interrupted resource trials and rejected candidates remain in the evidence. No installed SciPy, Sionna, DiffeRT or Blender file is patched.</p>
<p><a href="resource_validation.json">Initial resource experiments</a> · <a href="resource_selection.json">Final solver selection</a>. The <a href="https://docs.scipy.org/doc/scipy/reference/generated/scipy.sparse.linalg.splu.html">SciPy sparse LU documentation</a> and <a href="https://docs.scipy.org/doc/scipy/reference/generated/scipy.sparse.linalg.gmres.html">GMRES documentation</a> describe the numerical solver interfaces used. Solver documentation is not physical validation.</p>
<h2>Reproduce and verify</h2><pre>.\\Refine_Dielectric3D_Residual.ps1
.\\work\\d3res\\check_workflows.ps1
&amp; .\\work\\runtime\\Scripts\\python.exe -B .\\work\\github-update\\differt-bridge\\scripts\\build_dielectric3d_residual_report.py .
.\\Regenerate_Dielectric3D_Residual_Animation.ps1
&amp; .\\work\\runtime\\Scripts\\python.exe -B .\\work\\github-update\\differt-bridge\\scripts\\package_dielectric3d_residual.py . --clean-frames</pre>
<p><a href="verification.json">Final verification</a> · <a href="media_manifest.json">Media hashes</a> · <a href="native_workflow_health.json">Native Blender check</a> · <a href="reciprocal_blender.json">Reciprocal Blender check</a> · <a href="video_validation.json">Video decode and timeline reopen</a> · <a href="dielectric3d_residual_evidence.zip">Checksummed evidence</a> · <a href="analysis.json">Fields and metrics</a>. Prior reports and media are preserved. Temporary frame images are removed only after decoding and content checks.</p>
<p><a href="https://www.nist.gov/publications/numerical-experiments-scattering-dielectric-wedge">NIST's dielectric-wedge study</a> discusses numerical difficulties associated with singular transverse fields near an edge. It motivates convergence checks and does not validate this implementation.</p></body></html>'''
    for name in ('analysis.json','plan.json','resource_validation.json','resource_selection.json','sampling_validation.json','sampling_assessment.json','offgrid_validation.json','height_synthesis_validation.json','tail_addendum.json'):
        shutil.copyfile(w/name,out/name)
    (out/'index.html').write_text(page,encoding='utf-8');print(out/'index.html',flush=True)

if __name__=='__main__':main(Path(sys.argv[1]).resolve())
